export const KINDS=['tasks','sources','searches','observations','deliveries'];
export function emptyState(){return {schema_version:1,...Object.fromEntries(KINDS.map(k=>[k,[]]))};}
export function canonicalURL(raw){const u=new URL(raw);if(!['https:','http:'].includes(u.protocol)||u.username||u.password)throw Error('请使用不含登录凭据的 http/https 链接');u.hash='';for(const k of [...u.searchParams.keys()])if(k.toLowerCase().startsWith('utm_')||['fbclid','gclid','igshid','xsec_token','xsec_source','spm'].includes(k.toLowerCase()))u.searchParams.delete(k);u.searchParams.sort();return u.href;}
export function day(date=new Date()){return [date.getFullYear(),String(date.getMonth()+1).padStart(2,'0'),String(date.getDate()).padStart(2,'0')].join('-');}
export function monthsAgo(date,n){const d=new Date(date);const targetDay=d.getDate();d.setDate(1);d.setMonth(d.getMonth()-n);const last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(targetDay,last));return day(d);}
export function fingerprint(t){return JSON.stringify([t.topic.trim().toLowerCase().replace(/\s+/g,' '),t.mode,t.focus,t.depth,t.start,t.end,t.historyStart,t.historyEnd]);}
export function validateBundle(raw){if(!raw||raw.schema_version!==1)throw Error('不支持的文件格式，需要星迹 schema_version: 1');const out=emptyState();for(const k of KINDS){const a=raw[k]??[];if(!Array.isArray(a)||a.length>20000)throw Error('资料数量或格式不正确');out[k]=a.map(r=>{if(!r||typeof r!=='object'||typeof r.id!=='string'||!r.id||r.id.length>200)throw Error('每条记录需要有效编号');const v={...r};if(k==='tasks'){if(v.results!==undefined&&(!Array.isArray(v.results)||v.results.some(r=>!r||typeof r.id!=='string'||typeof r.title!=='string'||(r.content!==undefined&&typeof r.content!=='string'))))throw Error('Invalid task results');if(v.attachments!==undefined&&(!Array.isArray(v.attachments)||v.attachments.some(a=>!a||typeof a.id!=='string'||typeof a.name!=='string'||typeof a.size!=='number'||a.size<0)))throw Error('Invalid attachments');if(v.workflow_progress!==undefined&&(!v.workflow_progress||typeof v.workflow_progress!=='object'||Array.isArray(v.workflow_progress)))throw Error('Invalid workflow progress');}if(k==='sources'){v.canonical_url=canonicalURL(v.url);if(v.verification&&!['lead','verified','unavailable'].includes(v.verification))throw Error('资料状态无效');}if(k==='observations'){if(!v.source_id||!v.observed_at||!Number.isFinite(Date.parse(v.observed_at)))throw Error('热度快照缺少有效时间或来源');if(!v.metrics||typeof v.metrics!=='object'||Array.isArray(v.metrics)||Object.values(v.metrics).some(n=>n!==null&&(typeof n!=='number'||!Number.isFinite(n)||n<0)))throw Error('热度指标必须为非负数或空值');}return v;});}return out;}
export function mergeBundle(state,incoming){const out=structuredClone(state);const remap=new Map();for(const k of ['sources','tasks','searches','observations','deliveries']){for(const r0 of incoming[k]){const r={...r0};if(r.source_id)r.source_id=remap.get(r.source_id)||r.source_id;const idx=out[k].findIndex(x=>k==='sources'?canonicalURL(x.url)===r.canonical_url:x.id===r.id);if(idx>=0){const old=out[k][idx];if(k==='observations'){if(JSON.stringify(old)!==JSON.stringify(r))throw Error('快照编号冲突，请保留旧记录并使用新编号');continue;}if(k==='sources'){remap.set(r.id,old.id);r.id=old.id;r.task_ids=[...new Set([...(old.task_ids||[]),...(r.task_ids||[])])];if(old.verification==='verified'&&r.verification==='lead')r.verification='verified';}out[k][idx]=k==='tasks'?mergeTask(old,r):{...old,...r};}else{if(out[k].some(x=>x.id===r.id))throw Error('编号对应不同来源，请修正后导入');out[k].push(r);}}}for(const o of out.observations)if(!out.sources.some(s=>s.id===o.source_id))throw Error('快照引用不存在的来源');return out;}
export function promptFor(t){return `使用 $startrail-search（星迹·热点搜索）执行实际联网研究。\n\n主题：${t.topic}\n模式：${t.mode==='study'?'学习':'工作'}\n重点：${t.focus||'以任务相关性为先，提炼可用于当前任务的证据'}\n深度：${t.depth==='deep'?'深度研究':'先小批探索，再按缺口扩展'}\n近期范围：${t.start} 至 ${t.end}\n历史范围：${t.historyStart} 至 ${t.historyEnd}\n\n先查询本地研究记忆，再确定复用、刷新和新搜。工作与学习都研究近期内容和过往热点。默认最优先近三个月有可比证据的上升趋势；旧热点近期复兴也可纳入。当前任务采用上述近期窗口。\n按任务→场景→规划→来源→证据排序→交付逐层按需执行。先发现，再核验，最后只补关键缺口。发布日期、产品日期、采集时间分开；当前点赞不能证明增长，不跨平台直接相加。无增长证据标待验证。历史必需资料独立保障覆盖。\n输出近期上升、持续高热、新生待验证、历史对照，并解释每条如何用于任务。附原始链接、日期依据、增长依据、可信度及缺口，不编造来源和热度。\n将实际执行记录、来源与热度快照保存到SQLite，并导出schema_version:1的星迹JSON供网页导入。网页生成的入口仅是计划，不算已搜索完成。任务编号：${t.id}`;}
export function mergeTask(old,incoming){const next={...old,...incoming};for(const field of ['workflow_progress']){if(old[field]||incoming[field]){next[field]={...old[field]};for(const [key,row] of Object.entries(incoming[field]||{})){const prior=old[field]?.[key];next[field][key]=prior?.updated_at&&row.updated_at&&prior.updated_at>row.updated_at?prior:{...prior,...row};}}}for(const field of ['results','attachments'])if(old[field]||incoming[field]){const rows=new Map((old[field]||[]).map(r=>[r.id,r]));for(const r of incoming[field]||[]){const prior=rows.get(r.id);rows.set(r.id,prior?.updated_at&&r.updated_at&&prior.updated_at>r.updated_at?prior:{...prior,...r});}next[field]=[...rows.values()];}return next;}
